{
  "name": "Interview Copilot AI",
  "description": "A real-time AI interview assistant that listens to incoming questions, uses your resume and JD context, and drafts accurate responses using Gemini 3 Flash.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Message {
  id: string;
  role: 'user' | 'model' | 'system';
  content: string;
  timestamp: number;
}

export interface AppSettings {
  apiKey: string;
  autoSend: boolean;
  contextFiles: ContextFile[];
}

export interface ContextFile {
  id: string;
  name: string;
  content: string;
  type: 'resume' | 'jd' | 'custom';
}

export interface SpeechState {
  isListening: boolean;
  transcript: string;
  interimTranscript: string;
  error: string | null;
}

import { GoogleGenAI } from "@google/genai";
import { Message, ContextFile } from "../types";

export class GeminiService {
  private ai: GoogleGenAI | null = null;
  private modelName = "gemini-3-flash-preview";
  private currentKey: string | null = null;

  constructor(apiKey?: string) {
    if (apiKey) {
      this.init(apiKey);
    }
  }

  public init(apiKey: string) {
    this.currentKey = apiKey;
    this.ai = new GoogleGenAI({ apiKey });
  }

  public async generateResponse(
    userQuery: string,
    history: Message[],
    contextFiles: ContextFile[]
  ): Promise<string> {
    if (!this.ai) {
      throw new Error("API Key not set. Please configure it in settings.");
    }

    const contextBlock = contextFiles
      .map((f) => `--- START ${f.type.toUpperCase()} (${f.name}) ---\n${f.content}\n--- END ${f.type.toUpperCase()} ---`)
      .join("\n\n");

    const systemInstruction = `
You are an expert interview assistant helping Venu Madhav Pentala (the candidate) interview for a Data Engineer role at Goldman Sachs.
You have access to Venu's resume and the Job Description (JD).

GOAL: Provide a concise, high-impact, and natural-sounding answer that Venu can speak immediately.

GUIDELINES:
1. **Be Human:** Do not sound like a bot. Use natural phrasing.
2. **Be Direct:** Answer the question immediately. Do not fluff.
3. **Be Relevant:** Connect Venu's projects (e.g., DataToyAI, Apache NiFi pipelines, Healthcare ETL) to the JD requirements (Spark, Cloud, Low Latency).
4. **Context Aware:** If the user asks a follow-up, use the chat history.
5. **Length:** Keep spoken answers under 45-60 seconds unless asked for deep technical detail.

CONTEXT DATA:
${contextBlock}
`;

    // Convert history to Gemini format (simplified for single-turn mostly, but supporting multi-turn)
    // We will simulate a chat by concatenating meaningful history or using chat mode. 
    // Given the requirement for "Draft -> Send", we treat this as a fresh generation based on history + current prompt.

    // Construct the full prompt conversationally to ensure context is kept
    const chatHistoryText = history
        .filter(m => m.role !== 'system')
        .map(m => `${m.role === 'user' ? 'Interviewer' : 'Candidate'}: ${m.content}`)
        .join('\n');

    const fullPrompt = `
${chatHistoryText}
Interviewer (Current Question): ${userQuery}

Candidate (You):
`;

    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: [
            { role: 'user', parts: [{ text: fullPrompt }] }
        ],
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.7,
        }
      });

      return response.text || "I couldn't generate a response.";
    } catch (error: any) {
      console.error("Gemini API Error:", error);
      if (error.message?.includes("API key")) {
          return "Error: Invalid API Key. Please check settings.";
      }
      return `Error generating response: ${error.message}`;
    }
  }
}

export const geminiService = new GeminiService();

import { useState, useEffect, useCallback, useRef } from 'react';

// Extend Window interface for Web Speech API support
declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

interface UseSpeechRecognitionProps {
  onTranscriptChange: (transcript: string) => void;
  onSilence?: () => void;
  silenceTimeoutMs?: number;
}

export const useSpeechRecognition = ({ 
  onTranscriptChange, 
  onSilence, 
  silenceTimeoutMs = 2000 
}: UseSpeechRecognitionProps) => {
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);
  const silenceTimerRef = useRef<NodeJS.Timeout | null>(null);
  const finalTranscriptRef = useRef("");

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      setError("Browser does not support Speech Recognition.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsListening(true);
      setError(null);
    };

    recognition.onerror = (event: any) => {
      // Ignore 'no-speech' errors as they happen frequently in silence
      if (event.error !== 'no-speech') {
        console.error("Speech recognition error", event.error);
        setError(`Error: ${event.error}`);
        setIsListening(false);
      }
    };

    recognition.onend = () => {
      // Auto-restart if we didn't manually stop
      if (isListening) {
        try {
          recognition.start();
        } catch (e) {
          setIsListening(false);
        }
      } else {
        setIsListening(false);
      }
    };

    recognition.onresult = (event: any) => {
      let interimTranscript = '';
      let finalTranscriptChunk = '';

      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalTranscriptChunk += event.results[i][0].transcript;
        } else {
          interimTranscript += event.results[i][0].transcript;
        }
      }

      // If we have a final chunk, append it to our ref
      if (finalTranscriptChunk) {
        finalTranscriptRef.current += " " + finalTranscriptChunk;
      }

      // Combine historic final + current interim
      // Note: We only pass the *newly detected* text to the input usually, 
      // but here we want to stream into the input box.
      // To avoid duplication if the user edits the box, we will rely on 
      // the parent component handling the text update, but here we provide 
      // the stream of what is currently being said.

      const displayText = finalTranscriptChunk + interimTranscript;

      // We pass just the *current utterance* logic or the full stream. 
      // For this app, we want to append to the input box.
      if (displayText.trim()) {
        onTranscriptChange(displayText);

        // Reset silence timer
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

        if (onSilence) {
            silenceTimerRef.current = setTimeout(() => {
                onSilence();
            }, silenceTimeoutMs);
        }
      }
    };

    recognitionRef.current = recognition;

    return () => {
      if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, [isListening, onTranscriptChange, onSilence, silenceTimeoutMs]);

  const startListening = useCallback(() => {
    if (recognitionRef.current) {
      finalTranscriptRef.current = ""; // Reset internal buffer
      try {
        recognitionRef.current.start();
      } catch (e) {
        console.warn("Recognition already started");
      }
    }
  }, []);

  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  }, []);

  return { isListening, error, startListening, stopListening };
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Settings, Mic, Send, StopCircle, FileText, Upload, Plus, Trash2, Cpu, FileCheck } from 'lucide-react';
import { geminiService } from './services/geminiService';
import { useSpeechRecognition } from './hooks/useSpeechRecognition';
import { INITIAL_JD_TEXT, INITIAL_RESUME_TEXT } from './constants';
import { Message, AppSettings, ContextFile } from './types';

// Components defined in same file for single-file constraints (except hooks/services)
const Modal = ({ isOpen, onClose, title, children }: any) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-surface border border-gray-700 rounded-xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-4 border-b border-gray-700 flex justify-between items-center bg-gray-900/50">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">{title}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">✕</button>
        </div>
        <div className="p-6 overflow-y-auto custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
};

export default function App() {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showContext, setShowContext] = useState(false);

  const [settings, setSettings] = useState<AppSettings>({
    apiKey: localStorage.getItem("GEMINI_API_KEY") || "",
    autoSend: false,
    contextFiles: [
      { id: '1', name: 'Resume - Venu Madhav', content: INITIAL_RESUME_TEXT, type: 'resume' },
      { id: '2', name: 'Job Description - Goldman Sachs', content: INITIAL_JD_TEXT, type: 'jd' }
    ]
  });

  const chatContainerRef = useRef<HTMLDivElement>(null);

  // --- Initialization ---
  useEffect(() => {
    if (settings.apiKey) {
      geminiService.init(settings.apiKey);
    }
  }, [settings.apiKey]);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages]);

  // --- Speech Handling ---
  const handleTranscript = useCallback((textChunk: string) => {
    // Append new speech to input without overwriting manual edits if possible.
    // TextChunk here is coming from the hook which tries to give us the "latest" phrase.
    // For simplicity in this specialized app, we append.
    setInputText(prev => {
        // Simple heuristic: if the chunk is already at the end, don't double it.
        if (prev.endsWith(textChunk)) return prev;
        return prev + (prev ? " " : "") + textChunk;
    });
  }, []);

  const handleSilence = useCallback(() => {
    if (settings.autoSend && inputText.trim().length > 5) {
      console.log("Auto-sending due to silence...");
      handleSend();
    }
  }, [settings.autoSend, inputText]); // Note: inputText dependency here might be stale in callback, need ref in production but ok for this.

  const { isListening, error: speechError, startListening, stopListening } = useSpeechRecognition({
    onTranscriptChange: handleTranscript,
    onSilence: handleSilence,
    silenceTimeoutMs: 1500
  });

  // --- Logic ---
  const handleSend = async () => {
    if (!inputText.trim() || isProcessing) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText("");
    setIsProcessing(true);

    try {
      const responseText = await geminiService.generateResponse(
        userMsg.content,
        messages,
        settings.contextFiles
      );

      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (err) {
      console.error(err);
      const errorMsg: Message = {
        id: Date.now().toString(),
        role: 'system',
        content: "Error generating response. Please check your API Key.",
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const newFile: ContextFile = {
        id: Date.now().toString(),
        name: file.name,
        content: content,
        type: 'custom'
      };
      setSettings(prev => ({
        ...prev,
        contextFiles: [...prev.contextFiles, newFile]
      }));
    };
    reader.readAsText(file);
  };

  const removeFile = (id: string) => {
    setSettings(prev => ({
      ...prev,
      contextFiles: prev.contextFiles.filter(f => f.id !== id)
    }));
  };

  const toggleAutoSend = () => {
    setSettings(prev => ({ ...prev, autoSend: !prev.autoSend }));
  };

  const saveApiKey = (key: string) => {
    localStorage.setItem("GEMINI_API_KEY", key);
    setSettings(prev => ({ ...prev, apiKey: key }));
  };

  return (
    <div className="h-screen flex flex-col bg-background text-gray-100 font-sans overflow-hidden">

      {/* --- HEADER --- */}
      <header className="h-16 border-b border-gray-800 bg-surface/50 backdrop-blur-md flex items-center justify-between px-6 shrink-0 z-10">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
            <Cpu size={18} className="text-white" />
          </div>
          <h1 className="font-bold text-lg tracking-tight">Interview<span className="text-blue-400">Copilot</span></h1>
        </div>

        <div className="flex items-center gap-3">
           <div className={`px-3 py-1 rounded-full text-xs font-medium flex items-center gap-2 border ${isListening ? 'bg-red-500/10 border-red-500/50 text-red-400' : 'bg-gray-800 border-gray-700 text-gray-400'}`}>
              <div className={`w-2 h-2 rounded-full ${isListening ? 'bg-red-500 animate-pulse' : 'bg-gray-500'}`}></div>
              {isListening ? 'LISTENING TO INTERVIEWER' : 'MIC OFF'}
           </div>

           <button 
             onClick={() => setShowContext(true)}
             className="p-2 text-gray-400 hover:text-white hover:bg-gray-800 rounded-lg transition-all"
             title="Context & Files"
           >
             <FileText size={20} />
           </button>

           <button 
             onClick={() => setShowSettings(true)}
             className={`p-2 rounded-lg transition-all ${!settings.apiKey ? 'text-red-400 bg-red-900/20 animate-pulse' : 'text-gray-400 hover:text-white hover:bg-gray-800'}`}
             title="Settings"
           >
             <Settings size={20} />
           </button>
        </div>
      </header>

      {/* --- MAIN CONTENT --- */}
      <main className="flex-1 flex overflow-hidden relative">

        {/* Chat Area */}
        <div className="flex-1 flex flex-col max-w-5xl mx-auto w-full relative">

          {/* Messages */}
          <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-6 space-y-6 pb-32">
            {messages.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full text-gray-500 space-y-4 opacity-60">
                    <div className="w-16 h-16 rounded-full bg-gray-800 flex items-center justify-center">
                        <Mic size={32} />
                    </div>
                    <p className="text-center">
                        Ready to assist. <br/>
                        Ensure your input device is capturing the interviewer's voice.
                    </p>
                </div>
            )}

            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl p-4 shadow-lg ${
                  msg.role === 'user' 
                    ? 'bg-gray-800 text-gray-200 border border-gray-700 rounded-tr-sm' 
                    : msg.role === 'system'
                    ? 'bg-red-900/30 border border-red-800 text-red-200'
                    : 'bg-blue-600/10 border border-blue-500/20 text-blue-100 rounded-tl-sm'
                }`}>
                  <div className="text-xs font-semibold mb-1 opacity-50 uppercase tracking-wider">
                    {msg.role === 'user' ? 'Interviewer (Transcript)' : msg.role === 'system' ? 'System' : 'Suggested Answer'}
                  </div>
                  <div className="whitespace-pre-wrap leading-relaxed">
                    {msg.content}
                  </div>
                </div>
              </div>
            ))}
             {isProcessing && (
              <div className="flex justify-start">
                 <div className="bg-surface border border-gray-700 rounded-2xl p-4 rounded-tl-sm flex items-center gap-2 text-gray-400 text-sm">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0ms'}}></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '150ms'}}></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '300ms'}}></div>
                 </div>
              </div>
             )}
          </div>

          {/* --- BOTTOM CONTROL BAR --- */}
          <div className="bg-gradient-to-t from-background via-background to-transparent pt-10 pb-6 px-6 sticky bottom-0 z-20">
            <div className="max-w-4xl mx-auto">
                {/* Visualizer / Status */}
                {isListening && (
                    <div className="absolute -top-6 left-6 right-6 flex justify-center pointer-events-none">
                        <div className="bg-surface/90 backdrop-blur border border-red-500/30 text-red-400 px-4 py-1 rounded-full text-xs font-mono shadow-lg animate-pulse">
                            ● Listening for incoming voice...
                        </div>
                    </div>
                )}

                {speechError && (
                    <div className="absolute -top-12 left-0 right-0 flex justify-center">
                         <div className="bg-red-900/80 text-white px-4 py-1 rounded-lg text-sm border border-red-500">
                             {speechError}
                         </div>
                    </div>
                )}

                <div className="bg-surface border border-gray-700 rounded-xl p-2 shadow-2xl flex flex-col gap-2 relative ring-1 ring-white/5">

                    {/* Toolbar */}
                    <div className="flex items-center justify-between px-2 pt-1 pb-2 border-b border-gray-800">
                         <div className="flex items-center gap-2">
                            <button
                                onClick={isListening ? stopListening : startListening}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
                                    isListening 
                                    ? 'bg-red-500/20 text-red-400 hover:bg-red-500/30' 
                                    : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
                                }`}
                            >
                                {isListening ? <StopCircle size={14} /> : <Mic size={14} />}
                                {isListening ? 'Stop Listening' : 'Listen'}
                            </button>

                            <button
                                onClick={toggleAutoSend}
                                className={`text-xs px-2 py-1 rounded border transition-all ${settings.autoSend ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                            >
                                Auto-Send: {settings.autoSend ? 'ON' : 'OFF'}
                            </button>
                         </div>
                         <div className="text-xs text-gray-500 font-mono">
                            Gemini 3 Flash
                         </div>
                    </div>

                    {/* Input Area */}
                    <div className="relative">
                        <textarea
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            placeholder={isListening ? "Listening... (Start speaking or wait for transcript)" : "Transcript appears here. Edit before sending..."}
                            className="w-full bg-transparent text-gray-100 placeholder-gray-600 px-3 py-3 focus:outline-none resize-none min-h-[60px] max-h-[150px] font-medium"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    handleSend();
                                }
                            }}
                        />
                        <button 
                            onClick={handleSend}
                            disabled={!inputText.trim() || isProcessing}
                            className={`absolute bottom-3 right-3 p-2 rounded-lg transition-all ${
                                inputText.trim() && !isProcessing
                                ? 'bg-blue-600 text-white shadow-lg hover:bg-blue-500' 
                                : 'bg-gray-800 text-gray-500 cursor-not-allowed'
                            }`}
                        >
                            <Send size={18} />
                        </button>
                    </div>
                </div>
                <div className="text-center mt-2 text-[10px] text-gray-600">
                    Use a Virtual Cable or loopback device to route system audio to microphone for best results.
                </div>
            </div>
          </div>
        </div>
      </main>

      {/* --- SETTINGS MODAL --- */}
      <Modal isOpen={showSettings} onClose={() => setShowSettings(false)} title="Application Settings">
         <div className="space-y-6">
            <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">Gemini API Key (Required)</label>
                <input 
                    type="password"
                    value={settings.apiKey}
                    onChange={(e) => saveApiKey(e.target.value)}
                    placeholder="AIza..."
                    className="w-full bg-black/30 border border-gray-700 rounded-lg px-4 py-2 text-white focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-gray-500">
                    Enter your Gemini 3 Flash compatible API Key. This is stored locally in your browser.
                </p>
            </div>
         </div>
      </Modal>

      {/* --- CONTEXT MODAL --- */}
      <Modal isOpen={showContext} onClose={() => setShowContext(false)} title="Knowledge Base">
         <div className="space-y-6">
            <div className="flex justify-between items-center">
                <p className="text-sm text-gray-400">The AI uses these files to answer questions.</p>
                <label className="flex items-center gap-2 cursor-pointer bg-blue-600 hover:bg-blue-500 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors">
                    <Upload size={14} />
                    <span>Add File (.txt)</span>
                    <input type="file" accept=".txt" className="hidden" onChange={handleFileUpload} />
                </label>
            </div>

            <div className="grid gap-3">
                {settings.contextFiles.map((file) => (
                    <div key={file.id} className="bg-gray-800/50 border border-gray-700 rounded-lg p-3 flex items-start justify-between group">
                        <div className="flex items-start gap-3 overflow-hidden">
                            <div className={`mt-1 p-1.5 rounded-md ${file.type === 'resume' ? 'bg-purple-500/20 text-purple-400' : file.type === 'jd' ? 'bg-yellow-500/20 text-yellow-400' : 'bg-gray-700 text-gray-300'}`}>
                                {file.type === 'resume' ? <FileCheck size={16} /> : <FileText size={16} />}
                            </div>
                            <div>
                                <h4 className="font-medium text-sm text-gray-200 truncate pr-4">{file.name}</h4>
                                <p className="text-xs text-gray-500 mt-0.5 uppercase tracking-wider">{file.type}</p>
                            </div>
                        </div>
                        {file.type === 'custom' && (
                             <button onClick={() => removeFile(file.id)} className="text-gray-500 hover:text-red-400 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Trash2 size={16} />
                             </button>
                        )}
                    </div>
                ))}
            </div>

            <div className="bg-blue-900/10 border border-blue-800/30 rounded-lg p-4 text-xs text-blue-200/70">
                <strong>Note:</strong> Resume and Job Description are pre-loaded. Upload text files for additional project context or technical notes.
            </div>
         </div>
      </Modal>

    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';

// Extend Window interface for Web Speech API support
declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

interface UseSpeechRecognitionProps {
  onTranscriptChange: (transcript: string) => void;
  onSilence?: () => void;
  silenceTimeoutMs?: number;
}

export const useSpeechRecognition = ({ 
  onTranscriptChange, 
  onSilence, 
  silenceTimeoutMs = 2000 
}: UseSpeechRecognitionProps) => {
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);
  const silenceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const finalTranscriptRef = useRef("");

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      setError("Browser does not support Speech Recognition.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsListening(true);
      setError(null);
    };

    recognition.onerror = (event: any) => {
      // Ignore 'no-speech' errors as they happen frequently in silence
      if (event.error !== 'no-speech') {
        console.error("Speech recognition error", event.error);
        setError(`Error: ${event.error}`);
        setIsListening(false);
      }
    };

    recognition.onend = () => {
      // Auto-restart if we didn't manually stop
      if (isListening) {
        try {
          recognition.start();
        } catch (e) {
          setIsListening(false);
        }
      } else {
        setIsListening(false);
      }
    };

    recognition.onresult = (event: any) => {
      let interimTranscript = '';
      let finalTranscriptChunk = '';

      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalTranscriptChunk += event.results[i][0].transcript;
        } else {
          interimTranscript += event.results[i][0].transcript;
        }
      }

      // If we have a final chunk, append it to our ref
      if (finalTranscriptChunk) {
        finalTranscriptRef.current += " " + finalTranscriptChunk;
      }

      // Combine historic final + current interim
      // Note: We only pass the *newly detected* text to the input usually, 
      // but here we want to stream into the input box.
      // To avoid duplication if the user edits the box, we will rely on 
      // the parent component handling the text update, but here we provide 
      // the stream of what is currently being said.

      const displayText = finalTranscriptChunk + interimTranscript;

      // We pass just the *current utterance* logic or the full stream. 
      // For this app, we want to append to the input box.
      if (displayText.trim()) {
        onTranscriptChange(displayText);

        // Reset silence timer
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

        if (onSilence) {
            silenceTimerRef.current = setTimeout(() => {
                onSilence();
            }, silenceTimeoutMs);
        }
      }
    };

    recognitionRef.current = recognition;

    return () => {
      if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, [isListening, onTranscriptChange, onSilence, silenceTimeoutMs]);

  const startListening = useCallback(() => {
    if (recognitionRef.current) {
      finalTranscriptRef.current = ""; // Reset internal buffer
      try {
        recognitionRef.current.start();
      } catch (e) {
        console.warn("Recognition already started");
      }
    }
  }, []);

  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  }, []);

  return { isListening, error, startListening, stopListening };
};

import { useState, useEffect, useCallback, useRef } from 'react';

// Extend Window interface for Web Speech API support
declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

interface UseSpeechRecognitionProps {
  onTranscriptChange: (transcript: string) => void;
  onSilence?: () => void;
  silenceTimeoutMs?: number;
}

export const useSpeechRecognition = ({ 
  onTranscriptChange, 
  onSilence, 
  silenceTimeoutMs = 2000 
}: UseSpeechRecognitionProps) => {
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);
  const silenceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      setError("Browser does not support Speech Recognition.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true; // Keep true for activity detection, but we won't emit text
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsListening(true);
      setError(null);
    };

    recognition.onerror = (event: any) => {
      // Ignore 'no-speech' errors as they happen frequently in silence
      if (event.error !== 'no-speech') {
        console.error("Speech recognition error", event.error);
        setError(`Error: ${event.error}`);
        setIsListening(false);
      }
    };

    recognition.onend = () => {
      // Auto-restart if we didn't manually stop
      if (isListening) {
        try {
          recognition.start();
        } catch (e) {
          setIsListening(false);
        }
      } else {
        setIsListening(false);
      }
    };

    recognition.onresult = (event: any) => {
      let finalChunk = '';
      let hasInterim = false;

      // event.resultIndex is the index of the first result that has changed
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalChunk += event.results[i][0].transcript;
        } else {
          hasInterim = true;
        }
      }

      // Only send finalized text to the parent component
      // This prevents the "recording bullshit" (duplication of interim results)
      if (finalChunk) {
        onTranscriptChange(finalChunk);
      }

      // Reset silence timer if there is ANY speech activity (final or interim)
      if (finalChunk || hasInterim) {
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

        if (onSilence) {
            silenceTimerRef.current = setTimeout(() => {
                onSilence();
            }, silenceTimeoutMs);
        }
      }
    };

    recognitionRef.current = recognition;

    return () => {
      if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, [isListening, onTranscriptChange, onSilence, silenceTimeoutMs]);

  const startListening = useCallback(() => {
    if (recognitionRef.current) {
      try {
        recognitionRef.current.start();
      } catch (e) {
        console.warn("Recognition already started");
      }
    }
  }, []);

  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  }, []);

  return { isListening, error, startListening, stopListening };
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Settings, Mic, Send, StopCircle, FileText, Upload, Plus, Trash2, Cpu, FileCheck } from 'lucide-react';
