    }
  }, [settings.apiKey]);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages]);

  // --- Speech Handling ---
  const handleTranscript = useCallback((textChunk: string) => {
    // Simply append the new finalized chunk. 
    // The hook ensures we only get stable, finalized text.
    setInputText(prev => prev + (prev ? " " : "") + textChunk);
  }, []);

  const handleSilence = useCallback(() => {
    // We use a ref-like approach by accessing state in the callback, 
    // but we must be careful with stale closures. 
    // Since handleSilence is a dependency of the hook, and the hook updates when this changes,
    // we need to make sure this doesn't cause infinite re-renders of the hook.
    // However, in this component structure, relying on the 'settings.autoSend' prop passed to useCallback is standard.
    if (settings.autoSend && inputText.trim().length > 5) {
      console.log("Auto-sending due to silence...");
      handleSend();
    }
  }, [settings.autoSend, inputText]); 

  const { isListening, error: speechError, startListening, stopListening } = useSpeechRecognition({
    onTranscriptChange: handleTranscript,
    onSilence: handleSilence,
    silenceTimeoutMs: 1500
  });

  // --- Logic ---
  const handleSend = async () => {
    if (!inputText.trim() || isProcessing) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText("");
    setIsProcessing(true);

    try {
      // Pass the current messages state (which doesn't include userMsg yet in this closure)
      // This matches the service expectation of (query, history, context)
      const responseText = await geminiService.generateResponse(
        userMsg.content,
        messages, 
        settings.contextFiles
      );

      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (err) {
      console.error(err);
      const errorMsg: Message = {
        id: Date.now().toString(),
        role: 'system',
        content: "Error generating response. Please check your API Key settings.",
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleRegenerate = async () => {
    if (isProcessing) return;

    // Find the last user message
    const lastUserMsg = [...messages].reverse().find(m => m.role === 'user');
    if (!lastUserMsg) return;

    setIsProcessing(true);

    // Remove any trailing system/error messages or the previous AI response we want to replace
    // If the last message was a system error, we remove it.
    // If the last message was an AI response, we might want to re-roll it? 
    // Usually "Regenerate" implies re-doing the answer to the *last* question.
    setMessages(prev => {
        const newMsgs = [...prev];
        // Remove trailing system messages (errors)
        while (newMsgs.length > 0 && newMsgs[newMsgs.length - 1].role === 'system') {
            newMsgs.pop();
        }
        // Ideally we also remove the last AI message if we are regenerating *it*.
        // But the prompt implies "if I forget the api key... things will be lost". 
        // This implies the last message was likely an error or we just want to retry the last user input.
        return newMsgs;
    });

    try {
        // Calculate history EXCLUDING the last user message because generateResponse takes (query, history)
        // and appends query to history for the prompt.
        // The lastUserMsg is already in the 'messages' state, but 'generateResponse' logic
        // in our service treats the 'history' argument as "Previous Context".
        // We need to be careful not to duplicate the last turn.

        // Let's filter the history passed to the service.
        const historyForService = messages.filter(m => m.id !== lastUserMsg.id && m.role !== 'system');

        const responseText = await geminiService.generateResponse(
            lastUserMsg.content,
            historyForService,
            settings.contextFiles
        );

        const aiMsg: Message = {
            id: Date.now().toString(),
            role: 'model',
            content: responseText,
            timestamp: Date.now()
        };
        setMessages(prev => [...prev.filter(m => m.role !== 'system'), aiMsg]);

    } catch (err) {
        console.error(err);
        const errorMsg: Message = {
            id: Date.now().toString(),
            role: 'system',
            content: "Error regenerating response. Please check your API Key settings.",
            timestamp: Date.now()
        };
        setMessages(prev => [...prev, errorMsg]);
    } finally {
        setIsProcessing(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const newFile: ContextFile = {
        id: Date.now().toString(),
        name: file.name,
        content: content,
        type: 'custom'
      };
      setSettings(prev => ({
        ...prev,
        contextFiles: [...prev.contextFiles, newFile]
      }));
    };
    reader.readAsText(file);
  };

  const removeFile = (id: string) => {
    setSettings(prev => ({
      ...prev,
      contextFiles: prev.contextFiles.filter(f => f.id !== id)
    }));
  };

  const toggleAutoSend = () => {
    const nextState = !settings.autoSend;
    setSettings(prev => ({ ...prev, autoSend: nextState }));

    // If turning ON Auto-Send, immediately ensure we are listening.
    if (nextState && !isListening) {
        startListening();
    }
  };

  const saveApiKey = (key: string) => {
    localStorage.setItem("GEMINI_API_KEY", key);
    setSettings(prev => ({ ...prev, apiKey: key }));
  };

  return (
    <div className="h-screen flex flex-col bg-background text-gray-100 font-sans overflow-hidden">

      {/* --- HEADER --- */}
      <header className="h-16 border-b border-gray-800 bg-surface/50 backdrop-blur-md flex items-center justify-between px-6 shrink-0 z-10">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
            <Cpu size={18} className="text-white" />
          </div>
          <h1 className="font-bold text-lg tracking-tight">Interview<span className="text-blue-400">Copilot</span></h1>
        </div>

        <div className="flex items-center gap-3">
           <div className={`px-3 py-1 rounded-full text-xs font-medium flex items-center gap-2 border ${isListening ? 'bg-red-500/10 border-red-500/50 text-red-400' : 'bg-gray-800 border-gray-700 text-gray-400'}`}>
              <div className={`w-2 h-2 rounded-full ${isListening ? 'bg-red-500 animate-pulse' : 'bg-gray-500'}`}></div>
              {isListening ? 'LISTENING TO INTERVIEWER' : 'MIC OFF'}
           </div>

           <button 
             onClick={() => setShowContext(true)}
             className="p-2 text-gray-400 hover:text-white hover:bg-gray-800 rounded-lg transition-all"
             title="Context & Files"
           >
             <FileText size={20} />
           </button>

           <button 
             onClick={() => setShowSettings(true)}
             className={`p-2 rounded-lg transition-all ${!settings.apiKey ? 'text-red-400 bg-red-900/20 animate-pulse' : 'text-gray-400 hover:text-white hover:bg-gray-800'}`}
             title="Settings"
           >
             <Settings size={20} />
           </button>
        </div>
      </header>

      {/* --- MAIN CONTENT --- */}
      <main className="flex-1 flex overflow-hidden relative">

        {/* Chat Area */}
        <div className="flex-1 flex flex-col max-w-5xl mx-auto w-full relative">

          {/* Messages */}
          <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-6 space-y-6 pb-32">
            {messages.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full text-gray-500 space-y-4 opacity-60">
                    <div className="w-16 h-16 rounded-full bg-gray-800 flex items-center justify-center">
                        <Mic size={32} />
                    </div>
                    <p className="text-center">
                        Ready to assist. <br/>
                        Ensure your input device is capturing the interviewer's voice.
                    </p>
                </div>
            )}

            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl p-4 shadow-lg ${
                  msg.role === 'user' 
                    ? 'bg-gray-800 text-gray-200 border border-gray-700 rounded-tr-sm' 
                    : msg.role === 'system'
                    ? 'bg-red-900/30 border border-red-800 text-red-200'
                    : 'bg-blue-600/10 border border-blue-500/20 text-blue-100 rounded-tl-sm'
                }`}>
                  <div className="text-xs font-semibold mb-1 opacity-50 uppercase tracking-wider">
                    {msg.role === 'user' ? 'Interviewer (Transcript)' : msg.role === 'system' ? 'System' : 'Suggested Answer'}
                  </div>
                  <div className="whitespace-pre-wrap leading-relaxed">
                    {msg.content}
                  </div>
                </div>
              </div>
            ))}
             {isProcessing && (
              <div className="flex justify-start">
                 <div className="bg-surface border border-gray-700 rounded-2xl p-4 rounded-tl-sm flex items-center gap-2 text-gray-400 text-sm">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0ms'}}></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '150ms'}}></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '300ms'}}></div>
                 </div>
              </div>
             )}
          </div>

          {/* --- BOTTOM CONTROL BAR --- */}
          <div className="bg-gradient-to-t from-background via-background to-transparent pt-10 pb-6 px-6 sticky bottom-0 z-20">
            <div className="max-w-4xl mx-auto">
                {/* Visualizer / Status */}
                {isListening && (
                    <div className="absolute -top-6 left-6 right-6 flex justify-center pointer-events-none">
                        <div className="bg-surface/90 backdrop-blur border border-red-500/30 text-red-400 px-4 py-1 rounded-full text-xs font-mono shadow-lg animate-pulse">
                            ● Listening... (Interim text hidden for stability)
                        </div>
                    </div>
                )}

                {speechError && (
                    <div className="absolute -top-12 left-0 right-0 flex justify-center">
                         <div className="bg-red-900/80 text-white px-4 py-1 rounded-lg text-sm border border-red-500">
                             {speechError}
                         </div>
                    </div>
                )}

                <div className="bg-surface border border-gray-700 rounded-xl p-2 shadow-2xl flex flex-col gap-2 relative ring-1 ring-white/5">

                    {/* Toolbar */}
                    <div className="flex items-center justify-between px-2 pt-1 pb-2 border-b border-gray-800">
                         <div className="flex items-center gap-2">
                            <button
                                onClick={isListening ? stopListening : startListening}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
                                    isListening 
                                    ? 'bg-red-500/20 text-red-400 hover:bg-red-500/30' 
                                    : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
                                }`}
                            >
                                {isListening ? <StopCircle size={14} /> : <Mic size={14} />}
                                {isListening ? 'Stop Listening' : 'Listen'}
                            </button>

                            <button
                                onClick={toggleAutoSend}
                                className={`text-xs px-2 py-1 rounded border transition-all ${settings.autoSend ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                            >
                                Auto-Send: {settings.autoSend ? 'ON' : 'OFF'}
                            </button>
                         </div>
                         <div className="flex items-center gap-3">
                             {messages.some(m => m.role === 'user') && !inputText.trim() && !isProcessing && (
                                 <button
                                    onClick={handleRegenerate}
                                    className="flex items-center gap-1.5 text-xs text-blue-400 hover:text-blue-300 transition-colors"
                                    title="Retry last question"
                                 >
                                    <RefreshCw size={12} />
                                    Regenerate
                                 </button>
                             )}
                             <div className="text-xs text-gray-500 font-mono">
                                Gemini 3 Flash
                             </div>
                         </div>
                    </div>

                    {/* Input Area */}
                    <div className="relative">
                        <textarea
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            placeholder={isListening ? "Listening... Text will appear when speech pauses." : "Transcript appears here. Edit before sending..."}
                            className="w-full bg-transparent text-gray-100 placeholder-gray-600 px-3 py-3 focus:outline-none resize-none min-h-[60px] max-h-[150px] font-medium"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    handleSend();
                                }
                            }}
                        />
                        <button 
                            onClick={handleSend}
                            disabled={!inputText.trim() || isProcessing}
                            className={`absolute bottom-3 right-3 p-2 rounded-lg transition-all ${
                                inputText.trim() && !isProcessing
                                ? 'bg-blue-600 text-white shadow-lg hover:bg-blue-500' 
                                : 'bg-gray-800 text-gray-500 cursor-not-allowed'
                            }`}
                        >
                            <Send size={18} />
                        </button>
                    </div>
                </div>
                <div className="text-center mt-2 text-[10px] text-gray-600">
                    Use a Virtual Cable or loopback device to route system audio to microphone for best results.
                </div>
            </div>
          </div>
        </div>
      </main>

      {/* --- SETTINGS MODAL --- */}
      <Modal isOpen={showSettings} onClose={() => setShowSettings(false)} title="Application Settings">
         <div className="space-y-6">
            <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">Gemini API Key (Required)</label>
                <input 
                    type="password"
                    value={settings.apiKey}
                    onChange={(e) => saveApiKey(e.target.value)}
                    placeholder="AIza..."
                    className="w-full bg-black/30 border border-gray-700 rounded-lg px-4 py-2 text-white focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-gray-500">
                    Enter your Gemini 3 Flash compatible API Key. This is stored locally in your browser.
                </p>
            </div>
         </div>
      </Modal>

      {/* --- CONTEXT MODAL --- */}
      <Modal isOpen={showContext} onClose={() => setShowContext(false)} title="Knowledge Base">
         <div className="space-y-6">
            <div className="flex justify-between items-center">
                <p className="text-sm text-gray-400">The AI uses these files to answer questions.</p>
                <label className="flex items-center gap-2 cursor-pointer bg-blue-600 hover:bg-blue-500 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors">
                    <Upload size={14} />
                    <span>Add File (.txt)</span>
                    <input type="file" accept=".txt" className="hidden" onChange={handleFileUpload} />
                </label>
            </div>

            <div className="grid gap-3">
                {settings.contextFiles.map((file) => (
                    <div key={file.id} className="bg-gray-800/50 border border-gray-700 rounded-lg p-3 flex items-start justify-between group">
                        <div className="flex items-start gap-3 overflow-hidden">
                            <div className={`mt-1 p-1.5 rounded-md ${file.type === 'resume' ? 'bg-purple-500/20 text-purple-400' : file.type === 'jd' ? 'bg-yellow-500/20 text-yellow-400' : 'bg-gray-700 text-gray-300'}`}>
                                {file.type === 'resume' ? <FileCheck size={16} /> : <FileText size={16} />}
                            </div>
                            <div>
                                <h4 className="font-medium text-sm text-gray-200 truncate pr-4">{file.name}</h4>
                                <p className="text-xs text-gray-500 mt-0.5 uppercase tracking-wider">{file.type}</p>
                            </div>
                        </div>
                        {file.type === 'custom' && (
                             <button onClick={() => removeFile(file.id)} className="text-gray-500 hover:text-red-400 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Trash2 size={16} />
                             </button>
                        )}
                    </div>
                ))}
            </div>

            <div className="bg-blue-900/10 border border-blue-800/30 rounded-lg p-4 text-xs text-blue-200/70">
                <strong>Note:</strong> Resume and Job Description are pre-loaded. Upload text files for additional project context or technical notes.
            </div>
         </div>
      </Modal>

    </div>
  );
}
